"""Paper hashing findings and bounded positive mechanism."""
import hashlib,json,pathlib,runpy
H=pathlib.Path(__file__).resolve().parent;P='additional_operad_skills_remaining';runpy.run_path(str(H/(P+'_synthesis11.py')));fs=json.loads((H/(P+'_preparation.json')).read_text())['files'];p=H/(P+'.json');r=json.loads(p.read_text())
def e(i,a,b):return {'path':fs[i]['path'],'sha256':fs[i]['sha256'],'lines':[a,b]}
def f(n,t,b,ev,a,v,severity='medium'):return {'id':f'OPSKILL-F{n:03}','severity':severity,'title':t,'finding':b,'evidence':ev,'recommended_action':a,'validation':v}
rows=[
f(101,'Commit/reveal snippet treats unavailable or empty population as success','Verification runs only if the manifest exists, missing cases defaults to an empty list, and comparisons use assert. Missing evidence therefore produces no refusal and optimized Python removes hash comparisons; no timestamp/precommitment or blinding follows from digest equality alone.',[e(444,1,98)],'Require explicit nonempty exact case inventory, strict manifest shape/duplicates/path rules and unconditional mismatch errors; retain old commitment versions and independent chronology.','CHECK-086; source review of assertion and defaults.'),
f(102,'Paper extraction omits mathematical content from claim-statement bindings','Display-math branches continue before appending to an active claim buffer, so changing a displayed equation can leave claim statement hash/UUID unchanged. Claim-header lines also continue before inline extraction; numeric inline formulas are excluded and embedded display dollars are additionally parsed as inline. Exhaustive typed inventory is not achieved.',[e(448,353,409),e(448,411,489),e(448,491,554)],'Use one explicit grammar with disjoint formula spans; bind claim raw spans including displayed equations and preserve title/type/occurrences. Report rejected/unclosed syntax and extraction coverage rather than exhaustive labels.','CHECK-081/082 show duplicate classification, numeric exclusion and unchanged statement despite changed equation.','high'),
f(103,'Byte anchors describe newline-normalized text instead of source bytes','Markdown and TeX use read_text with universal newline conversion, then re-encode normalized strings to compute offsets. On CRLF files every preceding line shifts byte positions; location hashes contain no raw file digest to resolve representation ambiguity. Existing tests only check nonempty ranges.',[e(448,213,225),e(448,268,294),e(448,564,585),e(450,471,525)],'Read raw bytes, define decoding/newline representation explicitly, compute anchors against that representation and include raw source digest; test exact slicing with CRLF and Unicode.','CHECK-080 demonstrates reported2 versus actual3 for second-line start.'),
f(104,'ZIP checksum cross-check verifies names and can pass without bound modules','Digest columns in SHA256SUMS/MANIFEST are ignored; arbitrary suffix matches satisfy required names without unique rooted members or byte checks. Ancillary checksum/document requirements make required nonempty even when code/proof bindings are absent, bypassing advertised no-bindings refusal. Whole ZIP hash is useful custody but does not repair these missing checks.',[e(448,1096,1181),e(450,302,331)],'Separate binding presence from ancillary membership; validate digest syntax and each exact uniquely rooted regular member against expected bytes, reject duplicates/ambiguous paths, and name membership-only receipts accurately.','CHECK-083/084; existing source test accepts abc12345/def67890 as checksum columns.','high'),
f(105,'Paper coverage links are unverified ledger associations','Ledger entries become code/Lean bindings without file existence/hash/declaration/type checks; fallback number matching can associate a different claim kind. Regex Lean declaration names and inherited formula bindings are counted as coverage. Test fixture uses a True theorem and a pass function, so coverage is association coverage, not proof/implementation adequacy.',[e(448,648,675),e(448,677,792),e(450,368,428)],'Rename fields to association coverage or validate exact source/statement/premise bindings separately; preserve missing/ambiguous references and never infer proof from a path/name.','Full source inspection; no Lean/runtime replay or theorem correspondence claim.'),
f(106,'Identity CONSISTENT conflates missing metadata with verified parity','Missing author/version/date/PDF produces no mismatch; creator/author checks merely contain Carroll and PDF author flag is not enforced. Different full author names can pass, and fallback version1.0.0 is synthesized. Pydantic shape bounds do not enforce count/hash/key/reference consistency.',[e(448,1008,1047),e(449,44,57),e(449,136,154)],'Use explicit unavailable/partial/consistent/mismatch states, compare declared complete identities and validate manifest relationships/digests independently.','CHECK-085 covers all-missing identity case; model invariants inspected in full.')]
d={x['id']:x for x in r['findings']};d.update({x['id']:x for x in rows});r['findings']=list(d.values())
r['claims'].append({'id':'OPSKILL-C010','claim':'The paper hasher supplies a useful bounded textual-association catalog: display-formula alignment requires equal normalized TeX/Markdown hashes, while claim statements remain explicitly unmatched and PDF label presence is separate.','evidence':[e(448,794,838),e(450,334,365)],'dependencies':['Admitted regex extraction grammar and whitespace/delimiter normalization','Exact source representation and trusted hash implementation'],'limitations':['No mathematical-equivalence or theorem-proof check','Claim extraction, offsets, ledger association and ZIP checksum limits F102--106','No retained owner or test suite executed during this audit']})
r['claims']=list({x['id']:x for x in r['claims']}.values())
vp=H/(P+'_checks11.json');v={'path':'dag/reviews/'+vp.name,'sha256':hashlib.sha256(vp.read_bytes()).hexdigest(),'description':'Seven independent paper-hash/source-predicate controls; no owner execution.'};r['validation']=[x for x in r['validation']if x['path']!=v['path']]+[v];p.write_text(json.dumps(r,indent=2)+'\n')
(H/(P+'.md')).write_text('\n'.join(['# Operad skills audit — in progress','',f"**{r['full_source_read_count']}/{r['scope_count']} full bodies reviewed; {len(r['remaining_work'])} pending.** Exact hashes, ranges and manual assessments are in JSON.",'',f"{len(r['claims'])} claims, {len(r['findings'])} findings;85 observed independent controls and one unavailable shell control.",'','Useful mechanisms include scoped AST diagnostics, explicit finite witnesses and normalized textual cross-format matching. The paper receipt layer still omits formula content from claim hashes, normalizes bytes before computing offsets, and checks ZIP member names without their supplied checksums. These are custody/association limits, separate from mathematical validity.','','No original bytes changed and no retained workflow/provider/native execution occurred. Remaining scope remains explicit.'])+'\n');print(json.dumps({'full':r['full_source_read_count'],'findings':len(r['findings'])}))
